  "content": """"Device-bound kernel variants for 4096x4096: masked vs unmasked, BLOCK, math dtype."""
import json
import os
import sys
import time

import torch
import torch_npu
import triton
import triton.language as tl

sys.path.insert(0, 'tmp')

ART = os.environ.get('KGS_DEBUG_ARTIFACTS', '.')
DEV = 'npu:0'
res = {}


def dump():
    with open(os.path.join(ART, 'kvar.json'), 'w') as fh:
        json.dump(res, fh, indent=1, sort_keys=True)


def timed(fn, reps=300, warmup=60):
    for _ in range(warmup):
        fn()
    torch.npu.synchronize()
    t0 = time.perf_counter()
    for _ in range(reps):
        fn()
    t1 = time.perf_counter()
    torch.npu.synchronize()
    t2 = time.perf_counter()
    return {'submit_us': round((t1 - t0) / reps * 1e6, 1),
            'total_us': round((t2 - t0) / reps * 1e6, 1)}


@triton.jit
def _masked(A, B, N: tl.constexpr, BLOCK: tl.constexpr):
    off = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    m = off < N
    a = tl.load(A + off, m, other=0)
    b = tl.load(B + off, m, other=1)
    x = a.to(tl.float32)
    y = b.to(tl.float32)
    v = tl.where(y != y, float('nan'), tl.where(x == 0.0, 0.0, x * tl.log(y)))
    tl.store(A + off, v, m)


@triton.jit
def _unmasked(A, B, BLOCK: tl.constexpr):
    off = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    a = tl.load(A + off)
    b = tl.load(B + off)
    x = a.to(tl.float32)
    y = b.to(tl.float32)
    v = tl.where(y != y, float('nan'), tl.where(x == 0.0, 0.0, x * tl.log(y)))
    tl.store(A + off, v)


@triton.jit
def _unmasked_native(A, B, BLOCK: tl.constexpr):
